import com.danawa.search.analysis.dict.SynonymDictionary
import com.danawa.search.analysis.korean.KoreanWordExtractor
import com.danawa.util.CharVector
import com.danawa.util.TestUtil
import org.elasticsearch.common.logging.Loggers
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import java.io.BufferedOutputStream
import java.io.FileOutputStream

class KoreanWordExtractorTest {

    companion object {
        private val logger = Loggers.getLogger(KoreanWordExtractorTest::class.java, "")
    }

    @BeforeEach
    fun init() {
        TestUtil.setLogLevel(
            System.getProperty("LOG_LEVEL"),
            ProductNameTokenizer::class.java,
            ProductNameParsingRule::class.java,
            ProductNameAnalysisFilter::class.java
        )
    }

    @Test
    fun testUserDictionary() {
        if (TestUtil.launchForBuild()) return

        val dictionary = TestUtil.loadDictionary()!!
        val userDict = dictionary.getDictionary(ProductNameDictionary.DICT_USER, SetDictionary::class.java)
        val brandDict = dictionary.getDictionary(ProductNameDictionary.DICT_BRAND, CustomDictionary::class.java)
        val makerDict = dictionary.getDictionary(ProductNameDictionary.DICT_MAKER, CustomDictionary::class.java)
        val categoryDict = dictionary.getDictionary(ProductNameDictionary.DICT_CATEGORY, CustomDictionary::class.java)
        val synonymDict = dictionary.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary::class.java)
        val compoundDict = dictionary.getDictionary(ProductNameDictionary.DICT_COMPOUND, CompoundDictionary::class.java)
        val spaceDict = dictionary.getDictionary(ProductNameDictionary.DICT_SPACE, SpaceDictionary::class.java)
        val stopDict = dictionary.getDictionary(ProductNameDictionary.DICT_STOP, SetDictionary::class.java)
        val unitDict = dictionary.getDictionary(ProductNameDictionary.DICT_UNIT, SetDictionary::class.java)
        val unitSynDict = dictionary.getDictionary(ProductNameDictionary.DICT_UNIT_SYNONYM, SynonymDictionary::class.java)

        var word: CharSequence
        word = CharVector("JY\uBAA8\uD130\uC2A4")
        logger.debug("CONTAINS {} = {}", word, userDict.contains(word))
        word = CharVector("jy\uBAA8\uD130\uC2A4")
        logger.debug("CONTAINS {} = {}", word, userDict.contains(word))
        word = CharVector("SANDISK")
        val synonyms = synonymDict.get(word)
        for (syn in synonyms) {
            logger.debug("SYNONYM:{}", syn)
        }

        var compareData = arrayOf("sandisk", "\uC608\uC77C\uAC00\uAD6C")
        compareData = arrayOf("z", "\uC9C0", "\uC81C\uD2B8", "zett", "jet", "sandisk", "\uC0B0\uB514\uC2A4\uD06C")

        for (key in compareData) {
            word = CharVector(key)
            val result = dictionary.find(word)
            logger.debug("")
            logger.debug("RESULT-FOR {}:{}", word, result)
            logger.debug("USER:{} / {}", userDict.contains(word), userDict.set().size)
            logger.debug("BRAND:{} / {} / {}", brandDict.map().containsKey(word), brandDict.map()[word], brandDict.wordSet.size)
            logger.debug("MAKER:{} / {} / {}", makerDict.map().containsKey(word), makerDict.map()[word], makerDict.wordSet.size)
            logger.debug("CATEGORY:{} / {} / {}", categoryDict.map().containsKey(word), categoryDict.map()[word], makerDict.wordSet.size)
            logger.debug("SYNONYM:{}{} / {}", "", synonymDict.get(word), synonymDict.wordSet.size)
            logger.debug("COMPOUND:{}{} / {}", "", compoundDict.get(word), synonymDict.wordSet.size)
            logger.debug("SPACE:{}{} / {}", "", spaceDict.get(word), spaceDict.wordSet.size)
            logger.debug("STOP:{} / {}", stopDict.contains(word), stopDict.set().size)
            logger.debug("UNIT:{} / {}", unitDict.contains(word), unitDict.set().size)
            logger.debug("UNITSYNONYM:{}{} / {}", "", unitSynDict.get(word), unitSynDict.wordSet.size)
            logger.debug("--------------------------------------------------------------------------------")
        }
    }

    @Test
    @Throws(Exception::class)
    fun testUnitDictionaryAdd() {
        if (TestUtil.launchForBuild()) return

        val dictionary = TestUtil.loadDictionary()!!
        val srcDict = dictionary.getDictionary(ProductNameDictionary.DICT_UNIT, SetDictionary::class.java)
        val tgtDict = SetDictionary()
        var count = 0
        for (word in srcDict.set()) {
            logger.debug("WORD:{}", word)
            tgtDict.addSourceLineEntry(word)
            count++
        }
        tgtDict.addSourceLineEntry(CharVector("%"))
        logger.debug("COUNT:{}", count)
        var ostream: BufferedOutputStream? = null
        try {
            ostream = BufferedOutputStream(FileOutputStream("/mnt/pub/Documents/workspace/TEST_HOME/esl-7.8.1/test.dict"))
            tgtDict.writeTo(ostream)
        } finally {
            try {
                ostream?.close()
            } catch (ignore: Exception) {
            }
        }
        dictionary.addDictionary(ProductNameDictionary.DICT_UNIT, tgtDict)
    }

    @Test
    fun testSynonymDictionary() {
        if (TestUtil.launchForBuild()) return

        val dictionary = TestUtil.loadDictionary()!!
        val synonymDict = dictionary.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary::class.java)
        var word: CharSequence
        word = CharVector("sandisk")
        word = CharVector("z")
        val words = ProductNameDictionary.getTwowaySynonymWord(word, synonymDict.map())
        logger.debug("SYNONYMS:{}", words)
    }

    @Test
    fun testSynonymsAlign() {
        if (TestUtil.launchForBuild()) return

        val synonymMap = HashMap<CharSequence, MutableList<CharSequence>>()
        makeSynonymMapData(synonymMap, "z", arrayOf("\uC9C0", "\uC81C\uD2B8"))
        makeSynonymMapData(synonymMap, "\uC9C0", arrayOf("z"))
        makeSynonymMapData(synonymMap, "\uC81C\uD2B8", arrayOf("zett", "z", "JET"))

        ProductNameDictionary.normalizeSynonymMap(synonymMap)
        val list = ArrayList<CharSequence>()
        logger.debug("ALLIGNED-MAP:{}", synonymMap)
        if (synonymMap.size > 1) {
            list.addAll(synonymMap.keys.toSortedSet(compareBy { it.toString() }))
        }
        logger.debug("TWO-WAY-SYNONYM:{}", list)
    }

    private fun makeSynonymMapData(
        map: MutableMap<CharSequence, MutableList<CharSequence>>,
        key: String,
        data: Array<String>
    ) {
        val list = ArrayList<CharSequence>()
        for (item in data) {
            list.add(CharVector(item, true))
        }
        map[CharVector(key, true)] = list
    }

    @Test
    fun testExtractorSimple() {
        if (TestUtil.launchForBuild()) return

        val dictionary = TestUtil.loadDictionary()!!
        val extractor = KoreanWordExtractor(dictionary)
        var str = "\uD55C\uAE00\uBD84\uC11D\uAE30\uD14C\uC2A4\uD2B8\uC911\uC785\uB2C8\uB2E4"
        // str = "/F20005W_F10011M_F20246W_247W_251W_FMS10"
        str = "\uD398\uC774\uD37C \uBCDA\uAF43 \uD1A0\uD37C \uBD04\uC774"
        str = "\uD30C\uD2F0\uD574 \uBCDA\uAF43 \uD1A0\uD37C \uBD04\uC774"
        var st = 0
        var ed = 0
        val cbuf = str.toCharArray()
        val cv = CharVector(cbuf, 0, str.length)
        var found: Boolean
        for (inx in cbuf.indices) {
            found = false
            if (cbuf[inx] == ' ') {
                ed = inx - 1
                found = true
            } else if (inx == cbuf.size - 1) {
                ed = inx
                found = true
            }
            if (ed - st + 1 <= 0) {
                found = false
            }
            if (found) {
                cv.offset(st)
                cv.length(ed - st + 1)
                logger.debug("SET-INPUT:{} / {}", cv, ed - st + 1)
                if (extractor.setInput(cbuf, cv.offset(), cv.length()) != -1) {
                    var entry = extractor.extract()
                    while (entry != null) {
                        logger.debug(">> {}", entry.toDetailString(cbuf))
                        entry = entry.next()
                    }
                }
                st = inx + 1
            }
        }
        assertTrue(true)
    }
}

