    @Test
    fun testSynonymsAlign() {
        if (TestUtil.launchForBuild()) return

        val synonymMap = HashMap<CharSequence, MutableList<CharSequence>>()
        makeSynonymMapData(synonymMap, "z", arrayOf("\uC9C0", "\uC81C\uD2B8"))
        makeSynonymMapData(synonymMap, "\uC9C0", arrayOf("z"))
        makeSynonymMapData(synonymMap, "\uC81C\uD2B8", arrayOf("zett", "z", "JET"))

        ProductNameDictionary.normalizeSynonymMap(synonymMap)
        val list = ArrayList<CharSequence>()
        logger.debug("ALLIGNED-MAP:{}", synonymMap)
        if (synonymMap.size > 1) {
            list.addAll(synonymMap.keys.toSortedSet(compareBy { it.toString() }))
        }
        logger.debug("TWO-WAY-SYNONYM:{}", list)
    }

    private fun makeSynonymMapData(
        map: MutableMap<CharSequence, MutableList<CharSequence>>,
        key: String,
        data: Array<String>
    ) {
        val list = ArrayList<CharSequence>()
        for (item in data) {
            list.add(CharVector(item, true))
        }
        map[CharVector(key, true)] = list
    }

    @Test
    fun testExtractorSimple() {
        if (TestUtil.launchForBuild()) return

        val dictionary = TestUtil.loadDictionary()!!
        val extractor = KoreanWordExtractor(dictionary)
        var str = "\uD55C\uAE00\uBD84\uC11D\uAE30\uD14C\uC2A4\uD2B8\uC911\uC785\uB2C8\uB2E4"
        // str = "/F20005W_F10011M_F20246W_247W_251W_FMS10"
        str = "\uD398\uC774\uD37C \uBCDA\uAF43 \uD1A0\uD37C \uBD04\uC774"
        str = "\uD30C\uD2F0\uD574 \uBCDA\uAF43 \uD1A0\uD37C \uBD04\uC774"
        var st = 0
        var ed = 0
        val cbuf = str.toCharArray()
        val cv = CharVector(cbuf, 0, str.length)
        var found: Boolean
        for (inx in cbuf.indices) {
            found = false
            if (cbuf[inx] == ' ') {
                ed = inx - 1
                found = true
            } else if (inx == cbuf.size - 1) {
                ed = inx
                found = true
            }
            if (ed - st + 1 <= 0) {
                found = false
            }
            if (found) {
                cv.offset(st)
                cv.length(ed - st + 1)
                logger.debug("SET-INPUT:{} / {}", cv, ed - st + 1)
                if (extractor.setInput(cbuf, cv.offset(), cv.length()) != -1) {
                    var entry = extractor.extract()
                    while (entry != null) {
                        logger.debug(">> {}", entry.toDetailString(cbuf))
                        entry = entry.next()
                    }
                }
                st = inx + 1
            }
        }
        assertTrue(true)
    }
}

