package com.danawa.search.analysis.product

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.util.TestUtil
import org.apache.lucene.analysis.TokenStream
import org.apache.lucene.analysis.tokenattributes.CharTermAttribute
import org.apache.lucene.analysis.tokenattributes.ExtraTermAttribute
import org.apache.lucene.analysis.tokenattributes.OffsetAttribute
import org.apache.lucene.analysis.tokenattributes.PositionIncrementAttribute
import org.apache.lucene.analysis.tokenattributes.SynonymAttribute
import org.apache.lucene.analysis.tokenattributes.TokenInfoAttribute
import org.apache.lucene.analysis.tokenattributes.TypeAttribute
import org.elasticsearch.common.logging.Loggers
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import java.io.Reader
import java.io.StringReader
import java.util.Scanner

class ProductNameAnalyzerTest {

    companion object {
        private val logger = Loggers.getLogger(ProductNameAnalyzerTest::class.java, "")

        @JvmStatic
        fun main(args: Array<String>) {
            println("\uD55C\uAE00\uC774 \uAE68\uC9C4\uB2E4\uBA74 IDE \uC2E4\uD589\uC2DC \uC778\uCF54\uB529 \uC124\uC815\uC744 \uD574\uC8FC\uC138\uC694. -Dfile.encoding=UTF-8")
            val test = ProductNameAnalyzerTest()
            val dictionary = TestUtil.loadDictionary()!!
            var sc: Scanner? = null
            try {
                sc = Scanner(System.`in`, "utf-8")
                println("\uBD84\uC11D\uD560 \uB2E8\uC5B4\uB97C \uC785\uB825\uD574\uC8FC\uC138\uC694:")
                while (true) {
                    val text = sc.nextLine() ?: break
                    logger.info("\"{}\"\uC758 \uBD84\uC11D\uACB0\uACFC.", text)
                    test.analyzeSimple(text, dictionary)
                    logger.info("-------------------------------------------------")
                    logger.info("\uBD84\uC11D\uD560 \uB2E8\uC5B4\uB97C \uC785\uB825\uD574\uC8FC\uC138\uC694:")
                }
            } finally {
                try {
                    sc?.close()
                } catch (ignore: Exception) {
                }
            }
        }
    }

    @BeforeEach
    fun init() {
        TestUtil.setLogLevel(
            System.getProperty("LOG_LEVEL"),
            ProductNameTokenizer::class.java,
            ProductNameParsingRule::class.java,
            ProductNameAnalysisFilter::class.java
        )
    }

    private fun analyzeSimple(text: String, dictionary: ProductNameDictionary) {
        var analyzer: ProductNameAnalyzer? = null
        var reader: Reader? = null
        try {
            val option = AnalyzerOption(true, true, true, true, true)
            analyzer = ProductNameAnalyzer(dictionary, option)
            reader = StringReader(text)
            val stream: TokenStream = analyzer.tokenStream("", reader)
            val tokenAttribute = stream.addAttribute(TokenInfoAttribute::class.java)
            val termAttribute = stream.addAttribute(CharTermAttribute::class.java)
            val offsetAttribute = stream.addAttribute(OffsetAttribute::class.java)
            val typeAttribute = stream.addAttribute(TypeAttribute::class.java)
            val addAttribute = stream.addAttribute(ExtraTermAttribute::class.java)
            val synonymAttributeAttribute = stream.addAttribute(SynonymAttribute::class.java)
            val positionIncrementAttribute = stream.addAttribute(PositionIncrementAttribute::class.java)
            stream.reset()
            while (stream.incrementToken()) {
                logger.info(
                    "TOKEN:{} / {}~{} / {} / {} // {} / POS_INC[{}]",
                    termAttribute,
                    offsetAttribute.startOffset(),
                    offsetAttribute.endOffset(),
                    tokenAttribute.ref().length,
                    typeAttribute.type(),
                    synonymAttributeAttribute.synonyms,
                    positionIncrementAttribute.positionIncrement
                )
                val iter = addAttribute.iterator()
                while (iter != null && iter.hasNext()) {
                    val next = iter.next()
                    logger.info(" - ADD:{} / {}", next, typeAttribute.type())
                }
            }
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try {
                analyzer?.close()
            } catch (ignore: Exception) {
            }
            try {
                reader?.close()
            } catch (ignore: Exception) {
            }
        }
    }

