        val dictionary: ProductNameDictionary = TestUtil.loadDictionary()!!
        var reader: BufferedReader? = null
        var tokenizer: Tokenizer? = null
        var option: AnalyzerOption
        var tstream: ProductNameAnalysisFilter

        var nanoTime: Long
        var amountTime: Long = 0
        var count = 0

        try {
            reader = BufferedReader(FileReader(textFile))
            var rl: String?
            while (reader.readLine().also { rl = it } != null) {
                logger.trace("TEST:{}", rl)
                tokenizer = ProductNameTokenizer(dictionary, false)
                tokenizer.setReader(StringReader(rl))
                option = AnalyzerOption(false, true, true, true, false)
                tstream = ProductNameAnalysisFilter(tokenizer, dictionary, option)
                tstream.reset()
                val termAttr = tstream.addAttribute(CharTermAttribute::class.java)
                val offsetAttr = tstream.addAttribute(OffsetAttribute::class.java)
                val typeAttr = tstream.addAttribute(TypeAttribute::class.java)

                nanoTime = System.nanoTime()
                try {
                    while (tstream.incrementToken()) {
                        logger.trace("TOKEN:{} / {}~{} / {}", termAttr, offsetAttr.startOffset(), offsetAttr.endOffset(), typeAttr.type())
                    }
                } catch (e: Exception) {
                    logger.debug("EXCEPTION ON {}", rl)
                    logger.error("", e)
                }
                nanoTime = System.nanoTime() - nanoTime
                amountTime += nanoTime

                if (count > 0 && count % 10000 == 0) {
                    logger.debug("{} TAKES {} milliseconds", count, (Math.round(amountTime * 100.0 / 1000000.0).toInt()) / 100.0)
                }
                if (count > 100000) break
                count++
            }
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try {
                reader?.close()
            } catch (ignore: Exception) {
            }
            try {
                tokenizer?.close()
            } catch (ignore: Exception) {
            }
        }

        logger.debug("AMOUNT TIME:{}", amountTime)

        assertTrue(true)
    }

